/* -------------------- OM9-L3-01-13-009 atomic scene transaction -------------------- */

#[test]
#[ignore = "requires an admitted native reader and the authored source fixture builder"]
fn m03_01_13_009() {
    let temp = Temp::new();
    let mm = fixture(&temp, "mm");

    // A corrupt archive leaves the document, selection and Undo journal untouched.
    let corrupt = temp.join("truncated.3dm");
    let bytes = std::fs::read(&mm).unwrap();
    std::fs::write(&corrupt, &bytes[..bytes.len() / 3]).unwrap();
    let mut controller = Controller::new(Document::new("atomic"), Limits::default()).unwrap();
    let before = controller.document().entities.len();
    let before_undo = controller.coordinator().undo_len();
    assert!(controller.import_3dm(&corrupt).is_err());
    assert_eq!(controller.document().entities.len(), before);
    assert_eq!(controller.coordinator().undo_len(), before_undo);

    // Cancellation before publication leaves no partial scene.
    let (mut canceled, canceled_id) = fresh_coordinator("canceled import");
    let token = Cancellation::default();
    token.cancel();
    assert!(
        host()
            .import(&mut canceled, canceled_id, &mm, &token)
            .is_err()
    );
    assert!(canceled.world().documents[&canceled_id].entities.is_empty());

    // A successful import is exactly one Undo step and restores the prior document.
    let mut seeded = Document::new("undo");
    let existing = Entity::new("existing", Geometry::Point([9.0, 9.0, 9.0]), None);
    let existing_id = existing.id;
    seeded.entities.insert(existing_id, existing);
    let mut controller = Controller::new(seeded, Limits::default()).unwrap();
    let before_undo = controller.coordinator().undo_len();
    let diagnostics = controller.import_3dm(&mm).expect("import for undo");
    assert!(!diagnostics.is_empty());
    assert!(controller.document().entities.len() > 1);
    assert_eq!(controller.coordinator().undo_len(), before_undo + 1);
    controller.undo().unwrap();
    assert_eq!(controller.document().entities.len(), 1);
    assert!(controller.document().entities.contains_key(&existing_id));
}

/* ------------------- OM9-L3-01-13-010 file picker and options dialog ------------------- */

#[test]
#[ignore = "requires an admitted native reader and the authored source fixture builder"]
fn m03_01_13_010() {
    let temp = Temp::new();
    let mm = fixture(&temp, "mm");

    // The native program is admitted by absolute path and trusted SHA-256 only.
    let path = native();
    let good = host();
    assert_eq!(good.program(), path.as_path());
    assert!(
        ThreeDmHost::admit(&path, [0u8; 32]).is_err(),
        "wrong digest must be refused"
    );
    assert!(
        ThreeDmHost::admit(Path::new("relative-native.exe"), sha256(&path)).is_err(),
        "relative native path must be refused"
    );

    // Options are validated before the native owner runs.
    let (mut coordinator, id) = fresh_coordinator("options");
    let options = ImportOptions {
        max_file_bytes: 0,
        ..ImportOptions::default()
    };
    assert!(
        host()
            .import_with_options(
                &mut coordinator,
                id,
                &mm,
                &options,
                &Cancellation::default()
            )
            .is_err()
    );
    assert!(coordinator.world().documents[&id].entities.is_empty());

    // The Matrix File menu exposes both 3DM entry points; the native dialog itself is manual.
    let mut app = MatrixApp::new(Document::new("3dm menu")).unwrap();
    let context = egui::Context::default();
    frame(&mut app, &context, vec![]);
    let startup = frame(&mut app, &context, vec![]);
    let file = text_positions(&startup, "File")
        .into_iter()
        .find(|position| position.y < 25.0)
        .expect("File top menu");
    click(&mut app, &context, file);
    let output = frame(&mut app, &context, vec![]);
    assert!(
        !text_positions(&output, "Import 3DM…").is_empty(),
        "Import 3DM menu entry missing"
    );
    assert!(
        !text_positions(&output, "Export 3DM…").is_empty(),
        "Export 3DM menu entry missing"
    );
}

